SELECT p.id AS position_id, CASE WHEN s.id = p.signal_id THEN 'ENTRY' ELSE 'EXIT' END AS role, s.id, s.symbol, s.interval_code, s.decision, s.original_decision, s.signal_mode, s.candle_open_time, s.generated_at, s.created_at, s.latest_price, s.stop_loss, s.take_profit, s.risk_reward_ratio, s.atr_percent, s.atr_entry_type, s.total_score, s.confidence_score, s.final_entry_allowed, s.primary_blocking_stage, s.selected_strategy, s.market_regime, s.data_quality_valid, s.btc_context_status, s.confluence_status, s.confluence_higher_decision, s.entry_authority FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal s ON s.id IN (p.signal_id, p.exit_signal_id) WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, role;